-- Add Korean localization for existing quest_greeting entries.
-- Only Korean locale columns are changed; other locales and base text are preserved.
SET NAMES utf8mb4;

UPDATE `quest_greeting` SET `content_loc1` = '서부 몰락지대에 사악한 타락의 기운이 스며들었습니다. 내가 로데론의 전장에서 임무를 수행하는 동안, 정직한 농부들의 터전은 악당과 살인마들의 소굴로 변하고 말았지요. 인민군에 당신의 도움이 필요합니다.' WHERE `entry` = 234 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리 소박한 집에 오신 것을 환영해요! 친근한 얼굴을 보니 항상 반갑네요. 그리고 팔다리도 정말 튼튼해 보이시고요. 제 남편과 저는 항상 농장 일을 도와줄 일손을 찾고 있답니다. 선량한 사람들이 대부분 떠나버려서 일손 구하기가 하늘의 별 따기거든요.' WHERE `entry` = 235 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 근방엔 문제 말고는 아무것도 없어. 그 바보 같은 살대안한테 아직 기회가 있을 때 떠나라고 말해보았지만 듣지를 않더군. 하지만 난 바보가 아니지. 버나와 나는 이 수레만 고쳐지는 대로 바로 떠날 걸세.' WHERE `entry` = 237 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '가끔은 하늘에 커다란 잿빛 먹구름이 떠서 우리에게 불운만 내릴까 싶어요. 처음엔 우리 땅에서 쫓겨나더니, 이젠 서부 몰락지대에서 나가지도 못하고 있잖아요. 모든 게 엉망진창이에요. 무슨 수든 내야 해요.' WHERE `entry` = 238 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '멀고 가까운 땅에서 온 모험가여 $b이상하고 기묘한 이들과의 만남이라네 $b하지만 나에게 물어보고 싶은 것이 있다면 $b먼저 간단한 일을 하나 마쳐야 한다네!' WHERE `entry` = 239 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어이쿠, 이런 새로운 문제들이 끊이지 않으니 이 근방의 질서를 유지하기가 보통 힘든 게 아닙니다! $n님, 부디 좋은 소식을 가져오셨기를 바랍니다...' WHERE `entry` = 240 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이봐요, 친구. 내 이름은 레미라오.$B동쪽 붉은마루 산맥에서 왔는데, 일거리를 찾으러, 일거리를 찾으러 왔다오. 뭐 좀... 뭐 좀 없소??' WHERE `entry` = 241 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '아하! 좋은 날입니다, $C님! 이리 와서 앉아 술이라도 한잔하세요. 눈빛을 보니 수완이 아주 좋아 보이시는데, 나와 대화를 나누는 게 결코 시간 낭비가 아니라는 걸 알게 되실 겁니다...' WHERE `entry` = 253 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하십니까, 시민이여. 어딘가 목적이 분명해 보이는 분이군요. 스톰윈드 군대에 무슨 일이라도 있으십니까?' WHERE `entry` = 261 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '쉬어라, $c. 그저 지나가는 길이라면 도로를 벗어나지 말고 낮에만 다니길 권하네. 만약 다크샤이어에 볼일이 있다면, 야간 파수대에 자네의 능력을 보태보는 건 어떤가. 우리의 실력은 의심할 여지가 없으나 수가 너무 적다네.' WHERE `entry` = 264 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '당신이 올 것이라는 걸 꽤 오래전부터 느끼고 있었습니다, $n. 별들의 운명에 그렇게 적혀 있었지요.' WHERE `entry` = 265 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '다크샤이어 마을에 오신 것을 환영합니다. 서기 달트리입니다. 무엇을 도와드릴까요?' WHERE `entry` = 267 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어서 오세요! 제 주방에 오신 것을 환영합니다! 이곳이 바로 붉은까마귀 여관의 최고 별미들이 탄생하는 곳이죠. 아, 이 기막힌 향기를 한번 맡아보세요!' WHERE `entry` = 272 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '문은 꼭 닫아두게, $c. 검은 기사단이 언제 다시 지나갈지 모르니까 말이야.' WHERE `entry` = 273 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어서 오세요. 자리에 앉으시고 출출하시면 식사라도 하세요. 바느질하느라 바빠 보여도 신경 쓰지 마세요. 듣고 있으니까요...' WHERE `entry` = 278 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '헉?!? 아. 데피아즈단 도둑이나... 야간 파수대 대원 같지는 않군요. 불쌍한 영혼을 봐서 좀 자비를 베풀어 주지 않겠습니까?' WHERE `entry` = 288 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '응? 안녕하신가, 젊은 $C. 온갖 괴물들이 배회하는 이곳까지 찾아오다니 정말 용감하구먼!$B$B자, 여기까지 왔으니 이 늙은 은둔자를 좀 도와주지 않겠나...' WHERE `entry` = 289 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, 모험가여. 눈은 잘 보이지 않지만, 1마일 밖에서도 $c의 발소리를 느낄 수 있다오. 수년간 자부심을 품고 스톰윈드를 지켜왔건만, 시력을 잃은 후로는 은퇴할 수밖에 없었지.' WHERE `entry` = 294 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '아조라의 탑에 오신 것을 환영합니다, 젊은 $C. 저는 테오크리투스라고 합니다.$B$B제게 볼일이라도 있으신가요? 아니면... 어쩌면 제가 당신에게 볼일이 있는 걸까요?' WHERE `entry` = 313 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '한가롭게 잡담할 시간이 없소, $N. 비가 내리기 전에 이 다리를 재건해야 하거든. 지금까지 모든 프로젝트를 제때, 예산 범위 내에서 끝마쳐왔는데 이제 와서 삐끗할 수는 없지.' WHERE `entry` = 341 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑네, $n. 내 소박한 정원에 온 것을 환영하네. 요며칠 날씨가 참 완벽했지. 풍성한 수확을 거둘 때까지 이 날씨가 잘 유지되기를 바라세.' WHERE `entry` = 342 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '붉은마루 산맥이 혼돈에 빠졌습니다!' WHERE `entry` = 344 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, $C. 일 때문에 온 거라면 시원한 맥주 한 잔 들고 와서 얘기나 나눕시다.' WHERE `entry` = 381 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '잡담할 시간은 없소, 시민이여. 하지만 오크들에 맞서 일손을 보탤 생각이 있다면 자네가 할 일을 찾아주지.' WHERE `entry` = 382 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '놀라지 마라, $r이여. 나는 오래전에 이 세상을 떠났으나 그대들에게 해를 끼칠 생각은 없다. 살면서 너무나 많은 죽음을 보아왔기에, 이제 내 유일한 바람은 평화뿐이다. 어쩌면 그대가 내 뜻을 도와줄 수 있을지도 모르겠구나.' WHERE `entry` = 392 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이봐요, 절 좀 도와줄 수 있나요? 지금 정말 절박한 상황이라서요...' WHERE `entry` = 415 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, $C. 친구여, 암울한 시기라오. 우리 마을이 포위당했거든! 검은바위 오크들은 돌파수 요새에서 공격해 오고, 그늘가죽 리아나들은 일갈라의 탑을 위협하고 있으며, 붉은마루 놀 무리는 세력을 키우고 있지. 휴가를 즐기러 온 게 아니길 바라오...' WHERE `entry` = 464 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하신가, $c. 자네가 컬젠 대령의 패거리라면 그 자리에서 베어버리겠지만, 우리를 도우러 온 거라면 내 말을 들어보게나...' WHERE `entry` = 469 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어두운 시기가 찾아왔습니다, $c... 머지않아 모든 것을 잃게 될 것입니다... 진정 빛의 길을 걷는 자들을 제외하고는 빛조차 모두를 버릴 때가 말입니다.' WHERE `entry` = 633 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '사방에 도둑놈들이 득실거렸어요! $b$b정말 끔찍했습니다. 동굴이 무너져 내렸어요. 제 형인 반장을 포함해서 채광 조합 사람들이 전부 죽은 것 같습니다.' WHERE `entry` = 656 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '케어빈 가문은 빛의 이름 아래 승리를 위해 싸웁니다. 빛 아래 제 사명은 언데드와의 싸움에 제 목숨을 바치는 것이지요. 케어빈 주인님께서는 제게 그늘숲의 흉악한 늑대인간들을 소탕하라는 과업을 내리셨습니다. 저를 도와주시겠습니까?' WHERE `entry` = 663 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, $c! 사냥하기 딱 좋은 날씨 아닌가요? 나는 멧돼지 사냥에서 꽤 쏠쏠한 재미를 보았다오. 자네도 한 번 도전해 보겠나?' WHERE `entry` = 714 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '밀림의 또 다른 멋진 날이군요! 이번 사냥은 아주 흥미진진할 겁니다, 직감이 들거든요. 바닐이 총기 정비를 마치는 대로 사냥 파티를 이끌고 덩굴 숲 깊은 곳으로 들어갈 생각입니다. 늙은 참전 용사가 퇴역 후를 보내기엔 제법 괜찮은 삶이죠, 안 그렇습니까?' WHERE `entry` = 715 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 근처에서는 발걸음을 조심하는 게 좋을 거다. 비록 네가 우리 패거리는 아니지만, 선을 넘으면 지팡이 맛을 보여주지 않을 거라는 뜻은 아니니까!' WHERE `entry` = 733 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '허어, 어서 오게. 돈벌이에 마다할 사람처럼 보이지는 않는군, 음? 눈빛만 봐도 알 수 있지. 나는 아제로스 작전 총감독인 모굴 케복이라고 하네. 자네가 원하는 게 부라면, 내가 일자리를 마련해 줄 수 있지.' WHERE `entry` = 737 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '$C이신가? 나는 레빌가즈 남작의 비서인 크라제크라고 하네. 이 밀림과 그 너머에서 일어나는 모든 일을 알고 있지. 톱니항의 기름 시세가 궁금한가? 아닌가? 일거리를 찾고 있는 건가? 그렇다면 내가 도움을 줄 수 있지.' WHERE `entry` = 773 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑네. 나는 그렐린 화이트비어드라고 하네. 영눈 골짜기에서 늘어나는 트롤들의 위협을 조사하러 왔다네. 내가 뭘 밝혀냈냐고? 좀 골치 아픈 문제라네...' WHERE `entry` = 786 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하시오, $c. 평소라면 스톰윈드 시민들을 보살피며 순찰을 돌고 있었겠지만, 대다수 경비병들이 다른 땅에서 싸우고 있소. 그래서 순찰을 도는 대신 이렇게 현상금을 내걸고 대리 업무를 맡고 있는 거요...' WHERE `entry` = 823 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '무슨 일로 레이크샤이어 법정과 존경하는 솔로몬 치안판사님을 찾아오셨소?' WHERE `entry` = 900 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '랙이 내게 가르쳐 준 한 가지가 있다면, 어떤 임무도 지루하지 않다는 것입니다. 탄돌 교각을 지키는 건 쉬운 일이어야 했습니다. 하지만 주력군이 얼라이언스와 함께 싸우러 간 사이에 우리는 수세에 몰렸고, 결국 던 모드르가 몰락하고 말았습니다.' WHERE `entry` = 1071 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '아시다시피 저는 항상 발굴단원이 되고 싶었지만, 수에 밝게 태어난 바람에 길드에서 장부 정리에 가장 적합하다고 결정했지 뭡니까! 제 젊은 날은 매일 공부, 또 공부의 연속이었답니다...' WHERE `entry` = 1105 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어서 오십시오, 시민이여. 블런트노즈라고 합니다. 정확히는 블런트노즈 치안판사죠. 저는 텔사마의 안녕을 책임지고 있는데, 절 믿으세요, 이 근방엔 항상 든든한 일손이 더 필요하답니다!' WHERE `entry` = 1139 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '음식을 맛보러 오셨다면 환영합니다! 스톰윈드... 아니 온 아제로스를 통틀어 이보다 훌륭한 요리는 찾을 수 없을 겁니다!$B$B다른 일로 오셨다면 간단히 말씀해 주세요. 준비해야 할 요리가 수두룩해서 일일이 신경 써야 하거든요.' WHERE `entry` = 1141 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '간담을 서늘하게 하고 바지를 적실 만큼 오싹한 이야기를 견딜 각오가 되어 있다면, 술 한 잔 들고 잠시 앉아 보게나...' WHERE `entry` = 1239 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '트로그 놈들! 신들이 날 괴롭히려고 이 땅에 저놈들을 풀어놓았음이 틀림없소! 광산을 4인치 더 파고 들어가면 트로그 때문에 2피트나 후퇴해야 하니 말이오!' WHERE `entry` = 1254 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '사랑하는 우리 아버지 아르킬루스 썬더브루께서 설립하신 썬더브루 양조장에 오신 것을 환영합니다! 몇 해 전 형인 그림부즈가 술에 취해 어디론가 사라진 뒤로 제가 이곳을 지키고 있지요.' WHERE `entry` = 1267 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이거 혈기 왕성한 젊은 $c 아니신가. 전장에서 내가 세운 공훈 이야기를 듣고 찾아온 게 틀림없군!$B$B지금은 한가하게 옛날이야기나 할 때가 아니네. 해야 할 위대하고 중요한 일들이 아주 많거든! 그러니 영광을 꿈꾸고 있다면, 오늘 운이 아주 좋은 줄 알게나...' WHERE `entry` = 1343 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '비록 지금은 이 유적지 발굴 작업이 좀 더디게 진행되고 있지만, 오래가지 않을 거라고 확신하네. 하지만 당장은 자네 같은 사람이 필요하군. 드워프 탐험가 길드를 도와줄 생각이 있나?' WHERE `entry` = 1344 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '지금 아주 중요한 일을 처리하는 중이라네. 발굴단의 업무 말이지. 자네가 똑같이 중요한 할 말이 있는 게 아니라면—그럴 리 없겠지만—이만 자리를 비켜주게나.' WHERE `entry` = 1356 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '양조사 연맹 놈들, 저주나 받아라! 놈들은 최고급 재료만 싹 쓸어가고, 우리는 여기서 곡물과 홉이나 겨우 구하고 있으니 말이야!' WHERE `entry` = 1374 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '스톰윈드 왕립 도서관보다 더 위대한 지식의 보물창고는 어디서도 찾을 수 없을 것이오!' WHERE `entry` = 1440 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하십니까, $C. 동쪽 보루 쪽으로 이동하실 때는 주의하십시오. 최근 정찰 보고에 따르면 그 지역의 스컬지 활동이 증가했다고 하니 각별히 조심하시기 바랍니다.' WHERE `entry` = 1495 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '아, 거기 당신! 내게 맡길 임무가 있는데, 이것이 얼마나 중요한지 설명하느라 시간을 허비하진 않겠소. 잘 들으시오.' WHERE `entry` = 1499 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '여러 상황을 고려했을 때, 그대가 무사하시길 바랍니다.\n\n잠시 앉아 내 이야기를 들어보십시오. 물론 비극적인 이야기입니다만, 결국 복수로 끝나기를 바라는 이야기이지요!' WHERE `entry` = 1500 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '붉은십자군이 우리 고향 땅을 침범하고 있소. 어리석은 광신도 놈들은 암흑 여왕님의 충성스러운 종복들이 자신들을 파멸로 이끌 것임을 깨닫지 못하고 있지.' WHERE `entry` = 1515 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '암흑 여왕님께서 도전을 내던지셨다. 그에 응하는 것은 바로 우리에게 달렸다.' WHERE `entry` = 1518 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하십니까, 저는 스톰윈드의 도시 건축가인 바로스 알렉스턴이라고 합니다.' WHERE `entry` = 1646 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이쪽이다, 이 쓸모없는 놈아...! 조금이라도 쓸모 있는 일을 하고 싶다면 퍼뜩 귀 기울여 들어라!' WHERE `entry` = 1719 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '나는 스톰윈드의 대군주, 볼바르 폴드라곤이다.' WHERE `entry` = 1748 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '치열한 싸움 속에서 일생의 너무나 많은 시간을 보낸 탓에, 평화로웠던 시절의 기억은 갈수록 아득해지는구나.' WHERE `entry` = 1776 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '왕립 연금술사 학회는 암흑 여왕님의 뜻을 받들어 새로운 역병을 완성하고, 아서스와 그 사악한 스컬지 군대를 이 세상에서 영원히 쓸어버릴 것입니다.' WHERE `entry` = 1937 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '키린 토는 내 경고에 귀를 기울이지 않았어! 얼라이언스는 가짜다. 아루갈은 무모한 바보일 뿐이지.' WHERE `entry` = 1938 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '형제와 함께 정찰 임무 중이었는데 이 농가에 갇히고 말았소. 데스스토커에게 당신의 도움이 필요하오!' WHERE `entry` = 1950 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, $C. 여기까지 왔다면 은빛소나무 숲이 적들로 가득 차 있다는 걸 알고 계실 거요. 포세이큰이 살아남으려면 저들을 쓸어버려야만 하오!' WHERE `entry` = 1952 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '나는 공직을 위해 자라고 교육받았소. 백성을 대표하는 자로서 말이지. 내 능력은 무기나 기술이 아니라, 언변과 설득력에 있다오.' WHERE `entry` = 1977 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '왕립 연금술사 학회는 암흑 여왕님의 뜻을 받들어 새로운 역병을 완성하고, 아서스와 그 사악한 스컬지 군대를 이 세상에서 영원히 쓸어버릴 것입니다.' WHERE `entry` = 2055 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 가마솥에서는 걸쭉한 녹색 거품이 보글보글 피어오르고 있습니다. 이름 모를 생물의 해골과 뼈, 장기들이 끈적한 즙 속을 떠다니고 있습니다...$B$B그리고 한때 강대했던 두 트롤의 해골이 수면 위로 천천히 떠오릅니다.$B$B바로 간줄라와 네즐리옥입니다.' WHERE `entry` = 2076 AND `type` = 1;
UPDATE `quest_greeting` SET `content_loc1` = '텔드랏실의 창조는 위대한 업적이었으나, 이제 세상은 평형을 되찾기 위해 바뀌어야 합니다.' WHERE `entry` = 2080 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '공성 전차는 모든 조종사의 자부심이지!' WHERE `entry` = 2092 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하신가, $c. 지금 가죽이 턱없이 부족해서 골치가 좀 아픈 참이라네.' WHERE `entry` = 2094 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '정보... 정찰병과 요원들을 통해 우리는 로데론의 정보 흐름을 통제하고 있소. 스컬지의 움직임과 거점까지, 모두 우리의 감시 아래에 있지...' WHERE `entry` = 2121 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '암흑 여왕님과 바리마트라스를 섬기기 위해, 우리는 인간 벌레들을 몰아내는 전선을 앞으로 밀어붙여야 합니다.' WHERE `entry` = 2215 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리 암흑 여왕님께서 그토록 갈망하시는 새로운 역병의 완성이 이제 머지않았습니다.' WHERE `entry` = 2216 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '대족장님께서 태어나고 자라신 곳이 이렇게 가까이에 있다니 감회가 새롭군요.' WHERE `entry` = 2229 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '일하러 온 것이길 바라오, $C. 해야 할 일은 산더미인데 호드도, 비밀결사대도, 오거놈들도 우리를 도와주지 않을 테니 말이오.' WHERE `entry` = 2263 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '남녘해안 치안판사 직책을 처음 제의받았을 때, 내 경력에 이렇게 일찍 요직을 맡게 되어 정말 기뻤다오.$B$B하지만 막상 와보니 차라리 스톰윈드에서 서류나 정리하고 있는 게 나았을지도 모르겠다는 생각이 드는구려.' WHERE `entry` = 2276 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '내 가문은 스톰윈드의 어떤 귀족들보다도 뛰어난 보석과 미술품 수집품을 자랑하지!$B$B그리고 우린 언제나 수집품의 규모를 더 늘리고 싶어 한다네...' WHERE `entry` = 2285 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '응? 님보야에게 볼일이라도 있나?' WHERE `entry` = 2497 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '뭐라고, 뭐라고?!? 우리는 다 돈을 벌어야 해... 가만히 서 있는다고 돈이 나오진 않지.' WHERE `entry` = 2498 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어이! 자네도 주먹 뼈 던지기 내기 한 판 하러 왔나?' WHERE `entry` = 2501 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하신가! 정령들께서 당신이 내 족장님을 도우러 왔다고 하더군. 아주 크게 말씀하시더군.' WHERE `entry` = 2519 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '야르... 내 시간을 쓸데없이 허비하지 않는 게 좋을 거다, 이 친구야!' WHERE `entry` = 2546 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리 임시 거처 대원들은 아라시 고원에 남은 얼마 안 되는 스트롬가드 영토를 사수하고 있소. 하지만 영토를 계속 잃어가고 있지...$B$B내게 할 말이 있다면 부디 희소식이길 바라오.' WHERE `entry` = 2700 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '대족장님 덕분에 우리가 갇혀 있던 옛 수용소의 폐허 속에서도 희망이 남아있어, 호드가 새로이 일어서고 있다.' WHERE `entry` = 2706 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 나무 게시판에는 허름하게 만들어진 수배 전단들이 붙어 있습니다.' WHERE `entry` = 2713 AND `type` = 1;
UPDATE `quest_greeting` SET `content_loc1` = '물러서! 가깝게 오지 마! 가방에 폭약이 가득 들어있고 난 쓸 준비가 되어 있다고! 우리 다 같이 날아가 버릴 거야!$B$BA, 신경 쓰지 말게. 딴 사람인 줄 알았어....' WHERE `entry` = 2785 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '본그립의 룬과 파멸 상점에 오신 것을 환영합니다, $c. 구경은 해도 되지만 손대지는 마십시오.$B$B이곳의 지식 중 일부는... 초심자를 위한 것이 아니니까요.' WHERE `entry` = 2786 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 황탄한 황야를 배회하는 걸 보니 자네도 궁지에 몰린 게 틀림없군, $c. 나처럼 말이야.$B$B아니면 미쳐서 여기까지 온 걸지도 모르지. 미친 나처럼.' WHERE `entry` = 2817 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '정말 황급한 탈출이었네, $c. 우리는 바닥에 못 박혀 있지 않거나 당장 들고 튈 수 있는 건 뭐든 챙겼지. 덕분에 물자가 좀 부족하다네.' WHERE `entry` = 2860 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리가 술 한잔 기울인 뒤 밤중에 그 빌어먹을 놈들이 들이닥쳤소. 안 그랬으면 우리가 놈들을 쳐부쉈을 거요, 장담하건대.$B$B이제 몇 명 빼고는... 다 죽어버렸지.' WHERE `entry` = 2910 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이봐요, $N.$B$B롯빌은 눈치가 좀 부족한 상사예요. 일에 너무 몰두한 나머지 가끔은 종복들이 밥을 먹었는지, 임금을 받았는지도 잊어버리죠.$B$B$B$B그렇다고 당신까지 고생할 필요는 없잖아요.' WHERE `entry` = 2920 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '마침 아주 잘 찾아오셨소, $c.$B$B제 이름은 롯빌 베리아투스, 비전학, 연금술, 공학 종합 학회의 창립 회원입니다. 우리는 아제로스의 지성 과학을 하나의 종합 학문으로 융합하는 것을 목표로 하고 있지요.' WHERE `entry` = 2921 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '자연의 숲에 타락의 기운이 침범하고 있네. 어떤 희생을 치르더라도 숲을 지켜내야 하네.' WHERE `entry` = 2930 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, $c. 살면서 부족에 자신의 가치를 증명하고자 하는 의욕 넘치는 타우렌을 수없이 보아왔지. 의욕이 지혜와 경험을 대신할 수는 없다는 사실을 잊어서는 안 되오.' WHERE `entry` = 2981 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '순찰자의 의무는 멀고어 평원을 여행하는 이들의 안전을 지키는 것이다. 타우렌의 고향 땅을 위협하는 자들은 우리의 손에 처벌을 받게 될 것이다.' WHERE `entry` = 2988 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 대지는 우리 부족에게 한없이 자비로웠소, $c. 우리는 이 축복에 감사해야 합니다.' WHERE `entry` = 2993 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '롬카, $c. 잡담할 시간은 없으니 서둘러 일에 착수합시다.' WHERE `entry` = 3139 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '나와 나누고 싶은 이야기라도 있소, $c... 이리 와서 내 곁에 앉으시오.' WHERE `entry` = 3188 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '도끼의 묵직한 손맛, 동료들의 함성, 얼굴에 튀는 피보라. 이것이야말로 전사가 갈망하는 것들이다, $n. 나는 호드의 이름으로 칼을 휘둘러 불모의 땅을 개척할 것이다.' WHERE `entry` = 3337 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '대지와 물, 그리고 하늘은 모두 하나이다. 그것을 나누어 보는 것은 그대의 눈이 그대를 속이기 때문이다. 대지의 어머니는 그 모든 것이자 그 이상이니라.' WHERE `entry` = 3338 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '괜찮은 소식이길 바란다...' WHERE `entry` = 3339 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '불모의 땅에는 우리 로데론의 연금술사들이 유용하게 쓸 만한 온갖 재료들이 숨겨져 있지.' WHERE `entry` = 3390 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '스랄이 오그리마 건설을 도와준 대가로 나와 우리 아이들에게 넉넉히 보수를 주었기에, 여기에 항구를 차리기로 결정했지. 우리는 거래의 대부분을 무법항의 레빌가즈 남작을 통해 진행하고 있다네.' WHERE `entry` = 3391 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리 부족이 살아남으려면 자연의 이치를 연구하고 그 비밀을 배워야 합니다.' WHERE `entry` = 3419 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '짐승을 사냥하려면 먼저 그 짐승을 알아야 한다. 그 삶의 방식을 배우고 존중해야 하지.$B$B그렇지 않은 것은 사냥이 아니다. 그것은 그저 도살일 뿐이다.' WHERE `entry` = 3441 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '그래, 그래, 좋아! 자네가 바로 내가 찾던 $r이로군!\n\n앉게! 이야기할 게 아주 많거든!!' WHERE `entry` = 3446 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '무슨 도움이 필요하신가요, $n? 그게 아니면 제가 확인할 화물이 있어서요.' WHERE `entry` = 3453 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '나, 아리니아 클라우드브레이크는 신탁의 숲의 신성함을 수호하는 임무를 맡았습니다.' WHERE `entry` = 3519 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '반갑소, $n. 당신 같은 $c들이 숲을 지키는 데 적극적으로 나서주는 모습을 보니 보기 좋군요.' WHERE `entry` = 3567 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '귀 기울이는 자에게 바람이 속삭입니다...$B$B당신에게도 들리십니까?' WHERE `entry` = 3616 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어둠의 세력이 국경을 침범하고, 고대의 오염이 다시 머리를 들며, 새로운 악이 이 땅의 위태로운 균형을 무너뜨리려 합니다. 이처럼 암울한 시기일수록 우리 모두 경계를 게을리해서는 안 됩니다.' WHERE `entry` = 3649 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '좋은 날입니다, 젊은이! 처리해야 할 일들이 좀 있는데 나를 도와주지 않겠나.' WHERE `entry` = 3663 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '흠... 이 전선을 여기에 꽂으면 피즐탄 기어에 전력이 공급되겠지만, 그러면 수력 플랜지에 다른 동력원이 필요해질 텐데... 어쩌면... 아, 안녕! 이봐요, 내가 만든 새로운 발명품을 시험해 보는 걸 도와주지 않겠어요?' WHERE `entry` = 3666 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리 엘프에게는 긴 역사가 있습니다. 이 역사가 우리를 괴롭히는 유령이 되어 돌아오지 않기를 바랄 뿐입니다.' WHERE `entry` = 3845 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '잿빛골짜기는 생명력이 넘치는 무성한 숲입니다. 약초를 찾아 그 비밀스러운 길을 걷는 것은 즐거운 일이지만, 조심해야 합니다. 이 숲에도 위험이 도사리고 있으니까요.' WHERE `entry` = 3847 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '자연의 균형은 매우 위태로워서 쉽게 무너지곤 합니다. 상황을 바로잡을 만큼 용감하십니까?' WHERE `entry` = 3848 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '정령들이 동요하고 있다!' WHERE `entry` = 3995 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '잘 듣게, 젊은 $c. 어둠 속의 속삭임에 귀 기울이게나. 이 혼란스러운 시기에 가르침을 줄 테니.' WHERE `entry` = 4046 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '돌발톱의 정령이 슬피 웁니다... 산봉우리에서부터 강물, 그리고 잘려 나간 죽어가는 나무들에 이르기까지 슬피 울고 있습니다.' WHERE `entry` = 4049 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '적절한 재료만 구하면 폭발물을 만들 수 있어. 투자개발회의 사업에 타격을 줄 뿐만 아니라 시선도 끌 수 있지.$B$B감탄한 거 다 알아, 하지만 이게 끝이 아니야... 곧 더 자세히 얘기해 주지.' WHERE `entry` = 4077 AND `type` = 0;
