UPDATE `quest_greeting` SET `content_loc1` = '좀 더 가까이 오게. 자네와 나, 둘이서 이야기할 중요한 일이 있거든.$B$B남들이 들어서 좋을 것 없는 이야기라 말이지...' WHERE `entry` = 4452 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '발 밑을 조심하시오. 우리 모두가 $R처럼 우뚝 선 키를 타고난 건 아니니 말이오.' WHERE `entry` = 4453 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '아하! 방금 봤어요? 이 새로운 자동 스패너가 내 새 유입 매니폴드 설계에 아주 딱 들어맞을 것 같군요.' WHERE `entry` = 4454 AND `type` = 0;
