UPDATE `quest_greeting` SET `content_loc1` = '해는 길어지는데, 이 땅의 분쟁은 끝날 기미가 보이지 않는군요. 주문을 외우는 마법사가 아니더라도 그 정도는 알 수 있지요. 검을 들 수 있을 때 무기를 잡으십시오, $c. 전쟁은 언제든 우리 문앞까지 찾아올 수 있고, 내가 틀리지 않았다면 당신은 그걸 즐기는 사람 같아 보이는군요.' WHERE `entry` = 4485 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '안녕하신가, $c.' WHERE `entry` = 4498 AND `type` = 0;
