UPDATE `quest_greeting` SET `content_loc1` = '얼라이언스와 전면전을 벌이고 있지는 않지만, 우리 사이엔 여전히 피가 흘러넘치고 있지.' WHERE `entry` = 4791 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어떤 사람들은 늪지대가 쓸모없다고 생각해... 아무짝에도 쓸모없다고들 말하지.' WHERE `entry` = 4792 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '테라모어에서 연구하는 건 흥미로운 일이지만, 이 마을에서 편안한 침대를 찾기란 여간 힘든 게 아니에요!' WHERE `entry` = 4794 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리가 이 세상에 자리 잡으려면, 학문과 희미해져 가는 인간으로서의 본능을 억누르는 의지를 통해서 그렇게 해야 할 것이오.' WHERE `entry` = 5204 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '더위에 너무 신경 쓰지 마시오. 황탄한 황야에서 더위는 가장 작은 걱정거리일 뿐이니까.' WHERE `entry` = 5394 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '얼라이언스는 잊혀진 땅에 많은 이권이 걸려 있지만, 우리의 지배력은 불안정하다오.$B$B우리를 도와주시겠소?' WHERE `entry` = 5396 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '센토아 부족들이 잊혀진 땅의 황무지를 지배하고 있소. 만약 결속한다면 끔찍한 세력이 되겠지만, 다행히도 그들은 단합하지 않고 서로 다투며 전쟁을 벌이고 있지.' WHERE `entry` = 5412 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '이 돼지우리 같은 곳이 좀 안락하진 않지만, 역사가 있는 곳이니 스토나드가 누군가에게는 중요하겠지. 그래서 우리가 여기 지내는 거라고 걸 수 있소. 풍경 때문은 절대 아니오. 고향 모습하곤 전혀 딴판이니까.' WHERE `entry` = 5591 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '내게 원하는 것이 무엇인가?' WHERE `entry` = 5598 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '여기 잊혀진 땅에서 할 일이 아주 많다네, $N. 로텐은 고객 중 한 명을 위한 시약을 구하는 동시에 잃어버린 물품들도 찾아오길 원하고 있지.$B$B우리를 도우러 온 김에 바로 시작해 보는 게 어때?' WHERE `entry` = 5638 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '스랄께서 해결하길 바라시는 주요 위협은 불타는 칼날단이라네. 악마에게 충성을 바친 호드의 무리들이지. 그들은 어둠의 마법을 연마하는 데만 몰두할 뿐, 이곳 칼림도어에서 스랄께서 그리시는 호드의 미래에는 전혀 관심이 없다네.' WHERE `entry` = 5641 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리의 유일한 희망은 이미 악화된 상황 속에서 유용한 무언가를 만들어내는 것이다.' WHERE `entry` = 5767 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리가 자연을 보호하고자 한다면, 그 힘을 받아들여야 합니다. 그리고 이 땅에 해를 끼치려는 자들에게 그 힘을 보여주어야 합니다.' WHERE `entry` = 5770 AND `type` = 0;
