UPDATE `quest_greeting` SET `content_loc1` = '대용광로의 열기를 견디지 못하는 자들도 있지만, 내겐 이 열기가 딱 적당하다네. 본격적으로 대장간 일을 하기엔 최고의 장소지.' WHERE `entry` = 6031 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리 땅을 둘러싼 어둠에 수없이 시험받게 될 것입니다, $N. 하지만 항상 준비된 자세를 유지할 수 있도록, 당신이 스스로의 힘을 극대화할 수 있는 과업들을 종종 내릴 것입니다.$B$B빛과 함께하시고, 덕을 잃지 마십시오.' WHERE `entry` = 6171 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '빛의 성기사에겐 수많은 시험이 기다리고 있습니다, $N. 당신이 열정을 잃지 않고 우리가 찬양하는 덕목들을 지켜나간다면, 앞으로도 우리의 길은 수없이 교차할 것임을 확신합니다.' WHERE `entry` = 6179 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '트로그와 문둥이 노움들이 배회하는 곳에 우리의 고향 놈리건이 서 있다.$B$B가족을 잃고, 집을 잃고 산산이 흩어졌지.$B$B아, 근심 없던 놈리건에서의 나날이 얼마나 그리운지. 하지만 그런 날은 더 이상 없다. 우리는 일어서야 한다! 놈리건을 구해야 한다!' WHERE `entry` = 6569 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '놈리건을 위하여!' WHERE `entry` = 6579 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '내 이름은 드란 드로퍼스이고, 여기 옆에 있는 멍청한 녀석은 내 아들 말톤이라오. 인양물이 필요하거나 인양물을 팔고 싶다면, 바로 우리와 이야기해야 할 거요!' WHERE `entry` = 6986 AND `type` = 0;
