UPDATE `quest_greeting` SET `content_loc1` = '고르두니 오거들이 우리 땅을 침범하고 있네. 우리는 페랄라스의 더럽혀진 유적에서 놈들과 싸우고자 하는 자들을 가능한 한 많이 보내고 있지.' WHERE `entry` = 7777 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '어떤 사람들은 우리가 이 사막에서 뭘 하고 있는지 궁금해하더군. 글쎄... 말해주면 자네도 안 떠나고 우리 이익을 나눠 먹으려고 할 거 아닌가!' WHERE `entry` = 7876 AND `type` = 0;
UPDATE `quest_greeting` SET `content_loc1` = '우리는 돈을 벌려고 여기 온 거요. 물건을 도둑맞는 건 돈 버는 방법이 아니지.' WHERE `entry` = 7882 AND `type` = 0;
