UPDATE `quest_greeting` SET `content_loc1` = '내 사업 계획에는 거대한 코도를 수용하는 건 포함되어 있지 않았는데... 차라리 수중 바구니 짜기 사업이나 시작할 걸 그랬소.' WHERE `entry` = 11596 AND `type` = 0;
